import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Collections;

public class TextRed {
    public static void main(String[] args) {
        try {
            BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
            int length = Integer.parseInt(br.readLine());
            String inputStr = br.readLine();
            br.close();

            int verbCount = 0;
            int currentCount = 0;
            boolean insideParentheses = false;
            ArrayList<Integer> maxLengths = new ArrayList<>();
            maxLengths.add(0);
            char[] chars = inputStr.toCharArray();

            for (char c : chars) {
                if (c == '(') {
                    insideParentheses = true;
                    if (currentCount != 0) {
                        maxLengths.add(currentCount);
                    }
                    currentCount = 0;
                } else if (c == ')') {
                    insideParentheses = false;
                } else if (!insideParentheses && c != '_') {
                    currentCount++;
                } else if (!insideParentheses && c == '_') {
                    maxLengths.add(currentCount);
                    currentCount = 0;
                }
            }
            if (currentCount != 0) {
                maxLengths.add(currentCount);
            }

            System.out.print(Collections.max(maxLengths) + " ");

            currentCount = 0;
            insideParentheses = false;
            for (char c : chars) {
                if (c == '(') {
                    insideParentheses = true;
                    currentCount = 0;
                } else if (c == ')') {
                    insideParentheses = false;
                    if (currentCount != 0) {
                        verbCount++;
                    }
                } else if (insideParentheses && c != '_') {
                    currentCount++;
                } else if (insideParentheses && c == '_') {
                    if (currentCount != 0) {
                        verbCount++;
                    }
                    currentCount = 0;
                }
            }

            System.out.print(verbCount);
        } catch (Exception e) {
            System.out.println(0 + " " + 0);
        }
    }
}
